def _dump(node):
    return ast.dump(node,include_attributes=False)


def _code_shape(code):
    return tuple(getattr(code,name) for name in ('co_code','co_names','co_varnames',
        'co_argcount','co_posonlyargcount','co_kwonlyargcount','co_flags',
        'co_freevars','co_cellvars'))+(tuple(_code_shape(value) if type(value)is CodeType
            else value for value in code.co_consts),)


def _top_code(module_code,name):
    matches=[value for value in module_code.co_consts if type(value)is CodeType
        and value.co_name==name and value.co_qualname==name]
    if len(matches)!=1:raise ValueError('one complete top-level duel owner required: '+name)
    return matches[0]


def _cooperative_duel_function(group,original):
    """Finite exact propagation only; reverse every substitution to the full FN."""
    name=original.name
    if group not in VIEW_SPECS or name not in VIEW_SPECS[group]:
        raise ValueError('one named finite complete duel source owner required')
    expected=ast.parse(EXPECTED_WHOLE_OWNER_SOURCES[group][name]).body
    if len(expected)!=1 or _dump(original)!=_dump(expected[0]):
        raise ValueError('complete reviewed duel function differs: '+name)
    if any(isinstance(node,(ast.Yield,ast.YieldFrom,ast.AsyncFunctionDef)) for node in ast.walk(original)):
        raise ValueError('original duel function must not already be cooperative')
    spec=VIEW_SPECS[group][name]
    counts={key:0 for key in spec}
    substitutions=[]
    old_wait=ast.parse("""try:
    state.progress('duel-scene-frame-byte-ack')
except Boundary:
    raise MovementContinuationBoundary(poll, frame, 'actual duel frame BYTE ACK requires external IRQ progress')
""").body[0]
    new_wait=ast.parse('frame = (yield DuelSceneWait(state, frame, state.sr, poll).validate())').body[0]
    wait_changes=[]

    class Lift(ast.NodeTransformer):
        def visit_Try(self,node):
            if group=='scene' and name=='_duel_scene_frame_ack_fields' and _dump(node)==_dump(old_wait):
                wait_changes.append(node)
                replacement=copy.deepcopy(new_wait)
                ast.increment_lineno(replacement,node.lineno-1)
                return ast.copy_location(replacement,node)
            return self.generic_visit(node)

        def visit_Call(self,node):
            node=self.generic_visit(node)
            if not isinstance(node.func,ast.Name) or node.func.id not in spec:return node
            before=copy.deepcopy(node);dependency=node.func.id
            counts[dependency]+=1
            node.func.id=IMPORT_ADAPTERS.get((group,name,dependency),dependency)
            substitutions.append((copy.deepcopy(before),copy.deepcopy(node)))
            return ast.copy_location(ast.YieldFrom(value=node),node)

    derived=Lift().visit(copy.deepcopy(original))
    if counts!=spec or len(wait_changes)!=(1 if (group,name)==('scene','_duel_scene_frame_ack_fields') else 0):
        raise ValueError('exact complete duel substitution counts differ: '+name)
    remaining=list(substitutions);restored_wait=[]

    class Inverse(ast.NodeTransformer):
        def visit_Assign(self,node):
            if group=='scene' and name=='_duel_scene_frame_ack_fields' and _dump(node)==_dump(new_wait):
                restored_wait.append(node)
                return ast.copy_location(copy.deepcopy(old_wait),node)
            return self.generic_visit(node)

        def visit_YieldFrom(self,node):
            for index,(before,after) in enumerate(remaining):
                if _dump(node.value)==_dump(after):
                    remaining.pop(index)
                    return ast.copy_location(copy.deepcopy(before),node)
            raise ValueError('unexpected non-admitted duel cooperative call')

    inverse=Inverse().visit(copy.deepcopy(derived))
    if remaining or len(restored_wait)!=len(wait_changes) or _dump(inverse)!=_dump(original):
        raise ValueError('complete original duel function inverse differs: '+name)
    ast.fix_missing_locations(derived)
    return derived,counts,len(wait_changes)


def _cooperative_duel_module(group,original_tree):
    tree=copy.deepcopy(original_tree);restored=copy.deepcopy(original_tree);seen=set();admissions=[]
    for index,node in enumerate(original_tree.body):
        if type(node)is not ast.FunctionDef or node.name not in VIEW_SPECS[group]:continue
        if node.name in seen:raise ValueError('duplicate duel source owner')
        seen.add(node.name)
        derived,counts,waits=_cooperative_duel_function(group,node)
        tree.body[index]=derived
        # Each inverse was checked against this original node; restore that exact
        # whole node to prove no other function/import/constant was substituted.
        restored.body[index]=node
        admissions.append(dict(group=group,function=node.name,propagations=counts,waits=waits))
    if seen!=set(VIEW_SPECS[group]) or _dump(restored)!=_dump(original_tree):
        raise ValueError('complete duel module source identity differs')
    actual_inverse=copy.deepcopy(tree)
    for index,node in enumerate(original_tree.body):
        if type(node)is ast.FunctionDef and node.name in seen:actual_inverse.body[index]=node
    if _dump(actual_inverse)!=_dump(original_tree):raise ValueError('whole duel business-module inverse differs')
    ast.fix_missing_locations(tree)
    return tree,admissions


class _DuelScenePrograms:
    """The finite37-function private graph; public business owners stay untouched."""
    def __init__(self,state):
        from . import business_duel as scene
        from ..high_level_dynamic_flows import business_duel as action
        from ..high_level_gameplay_flow import business_battle as battle
        self.state=checked_state(state)
        self.thread=threading.get_ident()
        self.modules=dict(scene=scene,action=action,battle=battle)
        self.originals={};self.views={};self.namespaces={};self.admissions=[]
        for group,module in self.modules.items():
            source=inspect.getsource(module)
            tree=ast.parse(source,filename=module.__file__)
            derived,admissions=_cooperative_duel_module(group,tree)
            plain_code=compile(tree,module.__file__,'exec',dont_inherit=True)
            derived_code=compile(derived,module.__file__,'exec',dont_inherit=True)
            namespace=dict(vars(module));self.namespaces[group]=namespace
            for name in VIEW_SPECS[group]:
                original=getattr(module,name)
                if (type(original)is not FunctionType or original.__module__!=module.__name__
                        or original.__name__!=name or original.__globals__ is not vars(module)
                        or original.__closure__ is not None or original.__code__.co_freevars
                        or inspect.isgeneratorfunction(original)):
                    raise ValueError('actual complete unwrapped duel function required: '+name)
                if _code_shape(_top_code(plain_code,name))!=_code_shape(original.__code__):
                    raise ValueError('loaded duel function differs from complete-module source: '+name)
                self.originals[group,name]=original
                view=FunctionType(_top_code(derived_code,name),namespace,name,original.__defaults__,None)
                view.__kwdefaults__=original.__kwdefaults__
                view.__annotations__=dict(original.__annotations__)
                if not inspect.isgeneratorfunction(view):
                    raise ValueError('complete duel propagation owner must be cooperative: '+name)
                self.views[group,name]=view
                namespace[name]=view
            self.admissions.extend(admissions)
        # Only these two actual call helpers consume cooperative callbacks. Other
        # presentation callers keep the original synchronous owner and namespace.
        bridge=self.views['battle','_presentation_call_fields']
        self.namespaces['scene']['_presentation_call_fields']=bridge
        self.namespaces['action']['_presentation_call_fields']=bridge
        self.namespaces['scene']['_persistent_duel_action_entry']=self.views['action','execute_indexed_duel_action_fields']
        self.namespaces['action']['_persistent_duel_active_wait']=self.views['scene','wait_active_duel_action_fields']
        self.namespaces['action']['_persistent_duel_either_wait']=self.views['scene','wait_either_duel_action_fields']
        self.namespaces['scene']['DuelSceneWait']=DuelSceneWait

    def require_current(self,state):
        if state is not self.state or threading.get_ident()!=self.thread:
            raise ValueError('duel continuation belongs to another Scene or thread')
        for (group,name),original in self.originals.items():
            if getattr(self.modules[group],name)is not original:
                raise ValueError('actual duel owner was rebound during its live invocation: '+name)

    def program(self,frame):
        self.require_current(self.state)
        return self.views['scene','run_duel_scene_fields'](self.state,frame)


@dataclass(frozen=True)
class DuelSceneWait:
    """One of thirteen actual0700 TST.B wait points; no clock or guessed ACK."""
    state: SceneState
    frame: FirstDeploymentFrame
    status_word: int
    poll: int

    @property
    def stage(self):return 'original_duel_frame'

    def validate(self):
        checked_state(self.state);_movement_frame(self.state,self.frame)
        uint(self.status_word,16);uint(self.poll,32)
        if self.poll not in POLL_POINTS:
            raise MovementContinuationBoundary(self.poll,self.frame,'poll is not an actual complete duel wait')
        if self.state.sr!=self.status_word or self.frame.status!=(self.status_word&31):
            raise ValueError('duel wait does not retain actual full Scene SR/CCR-X')
        return self


class PersistentDuelSession:
    """One complete26DB4 invocation through real loadout/actions and26D84 RTS.

    Incoming CALL LONG belongs to the actual caller. Nested2777A/277B8 CALLs,
    menu WORD saves, MOVEM fields and fixed nonlocal action-pop/fade paths remain
    physically live across waits, never reconstructed from a boundary snapshot.
    """
    entry_pc=0x26DB4
    completion_pc=0x26D84

    def __init__(self,state: SceneState,frame: FirstDeploymentFrame):
        self.state=checked_state(state);self.entry=_movement_frame(state,frame)
        if frame.status!=(state.sr&31):raise ValueError('duel entry CCR and full SR disagree')
        self._programs=_DuelScenePrograms(state)
        self._program=self._programs.program(frame)
        self._started=self._complete=self._failed=False
        self.waiting=self.result=None;self.suspensions=0

    @property
    def complete(self):return self._complete

    @property
    def failed(self):return self._failed

    def _take(self,received=None):
        self._programs.require_current(self.state)
        try:
            waiting=next(self._program) if received is None else self._program.send(received)
        except StopIteration as finished:
            self.result=_movement_frame(self.state,finished.value)
            if self.result.stack_cursor.base!=self.entry.stack_cursor.base:
                self._failed=True
                raise Boundary('completed duel did not retain its incoming original physical SP')
            if self.result.status!=(self.state.sr&31):
                self._failed=True
                raise ValueError('completed duel CCR and full Scene SR disagree')
            self.waiting=None;self._complete=True
            return self.result
        except BaseException:
            self._failed=True
            raise
        try:
            if type(waiting)is not DuelSceneWait or waiting.state is not self.state:
                raise ValueError('one actual same-Scene duel wait required')
            self.waiting=waiting.validate()
        except BaseException:
            self._failed=True
            raise
        self.suspensions+=1
        return self.waiting

    def start(self):
        self._programs.require_current(self.state)
        if self._started:raise ValueError('cannot replay original26DB4 initialization')
        self._started=True
        return self._take()

    def resume(self,returned: FirstDeploymentFrame,pc: int):
        self._programs.require_current(self.state)
        if not self._started or self._complete or self._failed or self.waiting is None:
            raise ValueError('one live suspended complete duel invocation required')
        returned=_movement_frame(self.state,returned);uint(pc,32)
        if pc!=self.waiting.poll:
            raise MovementContinuationBoundary(pc,returned,'IRQ did not return to this original duel poll')
        if returned.stack_cursor.base!=self.waiting.frame.stack_cursor.base:
            raise Boundary('IRQ return did not preserve actual nested duel CALL/WORD stack')
        if self.state.sr!=self.waiting.status_word or returned.status!=(self.state.sr&31):
            raise ValueError('actual IRQ RTE did not restore duel complete SR/CCR-X')
        return self._take(returned)


def run_duel_blocking_fields(state: SceneState,frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Retain the actual live Session at a real wait, never catch/replay failure."""
    session=PersistentDuelSession(state,frame)
    result=session.start()
    if type(result)is DuelSceneWait:
        boundary=MovementContinuationBoundary(result.poll,result.frame,'actual0700 duel IRQ progress required')
        boundary.duel_session=session;boundary.duel_wait=result
        raise boundary
    return result


def duel_scene_program(state: SceneState,frame: FirstDeploymentFrame):
    """Forward the existing whole26DB4 lifetime; its caller owns the outer LONG.

    The current PersistentDuelSession retains its37 finite source views and
    checks actual callable identities at every resume. No algorithm is copied.
    """
    session=PersistentDuelSession(state,frame)
    current=session.start()
    while type(current)is DuelSceneWait:
        returned=yield current
        current=session.resume(returned,current.poll)
    return current
